pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address payable caller, uint256 unlockTime, uint256 collectAmount) public {
        // Ensure caller is not the zero address to avoid edge cases
        vm.assume(caller != address(0));
        // Bound unlockTime to a reasonable range (e.g., not too far in the past/future)
        unlockTime = bound(unlockTime, 0, type(uint64).max);
        // Bound collectAmount to avoid overflow in balance calculations
        collectAmount = bound(collectAmount, 0, 100 ether);

        // Fund the caller with enough ETH
        uint256 initCallerBalance = 10 ether;
        vm.deal(caller, initCallerBalance);

        // Caller puts some ETH into the contract
        uint256 putAmount = 5 ether;
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Record caller's balance in Acc and contract balance before Collect
        (uint256 balanceBefore, ) = c.Acc(caller);
        uint256 contractBalanceBefore = address(c).balance;

        // Caller attempts to collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // If the call succeeded, check the invariant
        if (success) {
            (uint256 balanceAfter, ) = c.Acc(caller);
            uint256 contractBalanceAfter = address(c).balance;
            // The sum of caller's Acc balance and contract balance should be at least as large as before
            assertTrue(balanceAfter + contractBalanceAfter >= balanceBefore + contractBalanceBefore);
        }
    }
}

