pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 putAmount, uint256 collectAmount) public {
        vm.assume(caller != address(this) && caller != address(0));
        vm.assume(putAmount > 0 && putAmount <= 100 ether);
        vm.assume(collectAmount <= 100 ether);

        // Pre-fund caller for puts
        vm.deal(caller, 100 ether);

        // First put from caller
        vm.prank(caller);
        c.Put{value: putAmount}(block.timestamp + 100);

        // Another address puts something
        address other = address(123);
        vm.deal(other, 1 ether);
        vm.prank(other);
        c.Put{value: 0.5 ether}(block.timestamp + 100);

        // Get caller's balance before collect
        ( , uint256 balanceBefore) = c.Acc(caller);

        // Try to collect from caller
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        if (success) {
            ( , uint256 balanceAfter) = c.Acc(caller);
            assertTrue(balanceAfter <= balanceBefore, "Balance after collect should not exceed balance before");
        }
    }
}

