pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 putAmount1, uint256 putAmount2, uint256 collectAmount) public {
        // Bound and assume to avoid overflow/revert in reference
        putAmount1 = bound(putAmount1, 0, 10 ether);
        putAmount2 = bound(putAmount2, 0, 10 ether);
        collectAmount = bound(collectAmount, 0, 10 ether);
        vm.assume(caller != address(0) && caller != address(this));

        // Fund the caller with enough ether for puts
        vm.deal(caller, putAmount1 + putAmount2 + 1 ether);

        // First Put
        vm.prank(caller);
        (bool success1, ) = address(c).call{value: putAmount1}(abi.encodeWithSignature("Put(uint256)", block.timestamp));
        require(success1, "Put1 failed");

        // Second Put
        vm.prank(caller);
        (bool success2, ) = address(c).call{value: putAmount2}(abi.encodeWithSignature("Put(uint256)", block.timestamp));
        require(success2, "Put2 failed");

        // Attempt to Collect; if it reverts, we skip assertion
        vm.prank(caller);
        (bool collectSuccess, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        if (!collectSuccess) return;

        // After successful Collect, the caller's Acc balance should be equal to total puts minus collected amount
        // This is the invariant: the reference adds balances, the buggy version overwrites.
        uint256 expectedBalance = putAmount1 + putAmount2 - collectAmount;
        ( , uint256 actualBalance) = c.Acc(caller);
        assertTrue(actualBalance == expectedBalance, "Balance invariant violated");
    }
}

