pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, uint256 putAmount, uint256 collectAmount, uint256 unlockTimeDelta) public {
        vm.assume(sender != address(0) && sender != address(c));
        vm.assume(putAmount > 0 && putAmount <= 1e30);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);
        vm.assume(unlockTimeDelta >= 1 && unlockTimeDelta <= 1000000);

        // First, do a Put from sender
        vm.deal(sender, putAmount);
        vm.prank(sender);
        c.Put{value: putAmount}(block.timestamp + unlockTimeDelta);

        // Record the sender's balance in Acc after Put
        (uint256 unlockTime, uint256 balanceAfterPut) = c.Acc(sender);

        // Move time forward so unlockTime passes
        vm.warp(block.timestamp + unlockTimeDelta + 1);

        // Now try to Collect from sender
        vm.prank(sender);
        (bool success, ) = address(c).call{gas: gasleft()}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // If Collect succeeded, check the property: sender's balance should be >= balanceAfterPut
        if (success) {
            (uint256 newUnlockTime, uint256 newBalance) = c.Acc(sender);
            assertTrue(newBalance >= balanceAfterPut, "Put overwrote balance");
        }
    }
}

