pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount, uint timeSkip) public {
        vm.assume(caller != address(0));
        vm.assume(collectAmount <= type(uint256).max / 2);
        vm.assume(putAmount <= type(uint256).max / 2);

        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        uint balanceBefore = c.Acc(caller).balance;
        bool unlockTimePassed = block.timestamp > unlockTime;

        vm.warp(block.timestamp + timeSkip);

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        uint balanceAfter = c.Acc(caller).balance;
        bool condition = (balanceBefore >= c.MinSum() && balanceBefore >= collectAmount && unlockTimePassed) ? (success && balanceAfter == balanceBefore - collectAmount) : (!success && balanceAfter == balanceBefore);

        assertTrue(condition);
    }
}

