pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 putAmount, uint256 unlockTime, uint256 collectAmount) public {
        // Bound amounts to avoid overflow and ensure we start with enough ether
        putAmount = bound(putAmount, 0, 100 ether);
        collectAmount = bound(collectAmount, 0, 100 ether);
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 365 days);

        // Fund the contract with a large initial deposit so Put can later reduce balance
        vm.deal(address(this), 1000 ether);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: 1000 ether}("");
        require(sent, "initial fund failed");

        // Deal ether to caller and do a Put
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        uint256 balanceBefore = address(c).balance;

        // Attempt Collect
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        uint256 balanceAfter = address(c).balance;

        // If Collect succeeded, the balance must have decreased by exactly collectAmount
        if (ok) {
            assertTrue(balanceBefore - balanceAfter == collectAmount, "balance decrease mismatch");
        }
        // If it reverted, the balance must be unchanged
        if (!ok) {
            assertTrue(balanceBefore == balanceAfter, "balance unchanged on revert");
        }
    }
}

