pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount, uint256 unlockTime, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(collectAmount <= amount); // ensure balance >= collectAmount if Put happened
        vm.assume(collectAmount >= 0);

        // Record initial balance
        uint256 initialBalance = c.Acc(caller).balance;

        // Perform Put call only if amount > 0 to avoid zero-value calls
        if (amount > 0) {
            vm.deal(caller, amount);
            vm.prank(caller);
            c.Put{value: amount}(unlockTime);
        }

        // Now call Collect with the given collectAmount
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The rule: if the initial balance was 0, after Collect the balance must still be 0
        // Because without Put being effective (bug), balance remains 0, Collect reverts or does nothing
        if (initialBalance == 0) {
            assertTrue(c.Acc(caller).balance == 0);
        } else {
            // If there was a Put, the reference would increase balance; the bug prevents that
            // This test is about the case where balance never changes
            assertTrue(c.Acc(caller).balance == initialBalance + (amount > 0 ? amount : 0) - (success ? collectAmount : 0));
        }
    }
}

